cuda_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

#define TILE 16

// ---------------------------------------------------------------
// Kernel: computes C = A (M×K)  *  Bᵀ (K×N)
//   A : (M, K)  row‑major
//   B : (N, K)  row‑major (so Bᵀ is accessed implicitly)
//   C : (M, N)  row‑major
// ---------------------------------------------------------------
__global__ void matmul_fp16_kernel(const half* __restrict__ A,
                                   const half* __restrict__ B,
                                   half* __restrict__ C,
                                   int M, int N, int K) {
    __shared__ half As[TILE][TILE];
    __shared__ half Bs[TILE][TILE];

    const int tx = threadIdx.x;
    const int ty = threadIdx.y;

    const int row = blockIdx.y * TILE + ty;   // output row index
    const int col = blockIdx.x * TILE + tx;   // output col index

    float acc = 0.0f;
    const int tiles = (K + TILE - 1) / TILE;

    for (int t = 0; t < tiles; ++t) {
        const int a_col = t * TILE + tx;   // column inside A
        const int b_row = t * TILE + ty;   // row    inside B (i.e. column of Bᵀ)

        // Load A tile
        if (row < M && a_col < K)
            As[ty][tx] = A[row * K + a_col];
        else
            As[ty][tx] = __float2half(0.0f);

        // Load B tile (note: B is stored as (N, K))
        if (col < N && b_row < K)
            Bs[ty][tx] = B[col * K + b_row];
        else
            Bs[ty][tx] = __float2half(0.0f);

        __syncthreads();

        #pragma unroll
        for (int k = 0; k < TILE; ++k) {
            acc += __half2float(As[ty][k]) * __half2float(Bs[k][tx]);
        }

        __syncthreads();
    }

    if (row < M && col < N) {
        C[row * N + col] = __float2half(acc);
    }
}

// ---------------------------------------------------------------
// C++ wrapper called from Python
// ---------------------------------------------------------------
void matmul_fp16(torch::Tensor A, torch::Tensor B, torch::Tensor C) {
    const int M = A.size(0);
    const int K = A.size(1);
    const int N = B.size(0);   // B shape is (N, K)

    const dim3 block(TILE, TILE);
    const dim3 grid((N + TILE - 1) / TILE, (M + TILE - 1) / TILE);

    // The kernel works only with half precision
    const half* A_ptr = reinterpret_cast<const half*>(A.data_ptr<at::Half>());
    const half* B_ptr = reinterpret_cast<const half*>(B.data_ptr<at::Half>());
    half* C_ptr = reinterpret_cast<half*>(C.data_ptr<at::Half>());

    matmul_fp16_kernel<<<grid, block>>>(A_ptr, B_ptr, C_ptr, M, N, K);

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        throw std::runtime_error(cudaGetErrorString(err));
    }
}

// ---------------------------------------------------------------
PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("matmul_fp16", &matmul_fp16, "Half‑precision matmul (A * Bᵀ)");
}
'''

# Compile the inline extension
matmul_ext = load_inline(
    name='matmul_fp16_ext',
    cpp_sources='',
    cuda_sources=cuda_source,
    functions=['matmul_fp16'],
    verbose=False,
)

# ---------------------------------------------------------------
# PyTorch model that uses the custom kernel
# ---------------------------------------------------------------
class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        # Ensure inputs are half‑precision, contiguous and on the same device
        A = A.to(torch.float16).contiguous()
        B = B.to(torch.float16).contiguous()
        M, K = A.shape
        N, Kb = B.shape
        assert K == Kb, "Incompatible inner dimensions"

        C = torch.empty(M, N, dtype=torch.float16, device=A.device)
        matmul_ext.matmul_fp16(A, B, C)
        return C
